if mibBuilder.loadTexts: tmnxSysRollbackStarted.setDescription('[CAUSE] The tmnxSysRollbackStarted notification is generated when the\n         user initiates a revert of the rollback checkpoint file specified by\n         tmnxSysRollbackIndex and tmnxSysRollbackFileType. The value of\n         tmnxLogExecRollbackOpIndex indicates the row entry in the\n         TIMETRA-LOG-MIB::tmnxLogExecRollbackOpTable for this rollback revert\n         operation.\n\n         [EFFECT] The specified file is executed and system configuration may\n         change.\n\n         [RECOVERY] There is no recovery required for this notification.')
tmnxSysRollbackStatusChange = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 43)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysRollbackIndex"), ("TIMETRA-SYSTEM-MIB", "tmnxSysRollbackResult"), ("TIMETRA-SYSTEM-MIB", "tmnxSysRollbackFileType"), ("TIMETRA-LOG-MIB", "tmnxLogExecRollbackOpIndex"))
if mibBuilder.loadTexts: tmnxSysRollbackStatusChange.setStatus('current')
if mibBuilder.loadTexts: tmnxSysRollbackStatusChange.setDescription('[CAUSE] The tmnxSysRollbackStatusChange notification is\n         generated upon the completion of a rollback revert as specified\n         by tmnxSysRollbackIndex and tmnxSysRollbackFileType.  The value\n         of tmnxLogExecRollbackOpIndex indicates the row entry in the\n         TIMETRA-LOG-MIB::tmnxLogExecRollbackOpTable for this rollback\n         revert operation.\n\n         [EFFECT] The result is indicated by the value of\n         tmnxSysRollbackResult.\n\n         [RECOVERY] When the value of tmnxSysRollbackResult is none, inProgress\n         or success no recovery is required. When the value is failed, the user\n         should try to determine the reason for the failure. The user can\n         attempt a recovery by reverting back to a known good checkpoint. The\n         user may reboot the system with the bof pointing to a saved\n         configuration file.')
tmnxSysRollbackSaveStatusChange = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 44)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysRollbackSaveResult"), ("TIMETRA-SYSTEM-MIB", "tmnxSysRollbackFileType"))
if mibBuilder.loadTexts: tmnxSysRollbackSaveStatusChange.setStatus('current')
if mibBuilder.loadTexts: tmnxSysRollbackSaveStatusChange.setDescription('[CAUSE] The tmnxSysRollbackSaveStatusChange notification is generated\n         upon the completion of a rollback save as specified by\n         tmnxSysRollbackFileType.\n\n         [EFFECT] The result is indicated by value of\n         tmnxSysRollbackSaveResult.\n\n         [RECOVERY] When the value of tmnxSysRollbackSaveResult is none,\n         inProgress or success no recovery is required. When the value is\n         failed, the user should try to determine the reason for the failure.\n         The user can attempt a recovery by attempting the rollback save again.')
tmnxSysRollbackFileDeleteStatus = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 45)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysRollbackIndex"), ("TIMETRA-SYSTEM-MIB", "tmnxSysRollbackFileDeleteResult"), ("TIMETRA-SYSTEM-MIB", "tmnxSysRollbackFileType"))
if mibBuilder.loadTexts: tmnxSysRollbackFileDeleteStatus.setStatus('current')
if mibBuilder.loadTexts: tmnxSysRollbackFileDeleteStatus.setDescription('[CAUSE] The tmnxSysRollbackFileDeleteStatus notification is generated\n         upon the completion of a rollback file delete as specified by\n         tmnxSysRollbackIndex and tmnxSysRollbackFileType.\n\n         [EFFECT] The result is indicated by the value of\n         tmnxSysRollbackFileDeleteResult.\n\n         [RECOVERY] When the value of tmnxSysRollbackFileDeleteResult is none,\n         inProgress or success no recovery is required. When the value is\n         failed, the user should try to determine the reason for the failure.\n         The user can attempt a recovery by deleting the file again.')
ssiSyncRollbackOK = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 46))
if mibBuilder.loadTexts: ssiSyncRollbackOK.setStatus('current')
if mibBuilder.loadTexts: ssiSyncRollbackOK.setDescription('[CAUSE]  The ssiSyncRollbackOK event is generated when the\n         synchronization of rollback files between the primary\n         and secondary CPMs finishes without errors.\n\n         [EFFECT] Rollback files are synchronized.\n\n         [RECOVERY] No recovery is necessary.')
ssiSyncRollbackFailed = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 47)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSyncFailureReason"))
if mibBuilder.loadTexts: ssiSyncRollbackFailed.setStatus('current')
if mibBuilder.loadTexts: ssiSyncRollbackFailed.setDescription('[CAUSE] The ssiSyncRollbackFailed event is generated when the\n         synchronization of rollback files between the primary and secondary\n         CPMs is stopped due to errors. The tmnxSyncFailureReason will state\n         the reason for the failure.\n\n         [EFFECT] Rollback files are not synchronized.\n\n         [RECOVERY] The user should try to determine the cause of the failure\n         and can attempt synchronizing the files again.')
ssiSyncCertOK = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 48))
if mibBuilder.loadTexts: ssiSyncCertOK.setStatus('current')
if mibBuilder.loadTexts: ssiSyncCertOK.setDescription('[CAUSE]  The ssiSyncCertOK event is generated when the\n         synchronization of certificate files between the primary\n         and secondary CPMs finishes without errors.\n\n         [EFFECT] Certificate files are synchronized.\n\n         [RECOVERY] No recovery is necessary.')
ssiSyncCertFailed = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 49)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSyncFailureReason"))
if mibBuilder.loadTexts: ssiSyncCertFailed.setStatus('current')
if mibBuilder.loadTexts: ssiSyncCertFailed.setDescription('[CAUSE] The ssiSyncCertFailed event is generated when the\n         synchronization of certificate files between the primary and secondary\n         CPMs is stopped due to errors. The tmnxSyncFailureReason will state\n         the reason for the failure.\n\n         [EFFECT] Certificate files are not synchronized.\n\n         [RECOVERY] The user should try to determine the cause of the failure\n         and can attempt synchronizing the files again.')
persistencyFileSysThresRaised = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 50)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxPersistenceAffectedCpm"), ("TIMETRA-SYSTEM-MIB", "tmnxPersistencyClient"), ("TIMETRA-SYSTEM-MIB", "tmnxPersistencyFileLocator"), ("TIMETRA-SYSTEM-MIB", "tmnxPersistencyNotifyMsg"))
if mibBuilder.loadTexts: persistencyFileSysThresRaised.setStatus('current')
