persistencyFileSysThresCleared = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 51)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxPersistenceAffectedCpm"), ("TIMETRA-SYSTEM-MIB", "tmnxPersistencyClient"), ("TIMETRA-SYSTEM-MIB", "tmnxPersistencyFileLocator"), ("TIMETRA-SYSTEM-MIB", "tmnxPersistencyNotifyMsg"))
if mibBuilder.loadTexts: persistencyFileSysThresCleared.setStatus('current')
if mibBuilder.loadTexts: persistencyFileSysThresCleared.setDescription('The persistencyFileSysThresCleared notification is generated when the\n         filesystem drops below 90 percent occupation.')
tmnxSysExecStarted = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 52)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysExecScript"), ("TIMETRA-LOG-MIB", "tmnxLogExecRollbackOpIndex"), ("TIMETRA-LOG-MIB", "tmnxLogExecRollbackOpType"))
if mibBuilder.loadTexts: tmnxSysExecStarted.setStatus('current')
if mibBuilder.loadTexts: tmnxSysExecStarted.setDescription("[CAUSE] The tmnxSysExecStarted notification is generated when the user\n         initiates a CLI 'exec' operation to process a file of SROS CLI\n         commands or processing of 'vsd' configuration messages have been\n         initiated.\n\n         The value of tmnxSysExecScript indicates the command file when the\n         value of tmnxLogExecRollbackOpType is 'exec' or an empty string when\n         the value of tmnxLogExecRollbackOpType is 'vsd'. The value of\n         tmnxLogExecRollbackOpIndex indicates the row entry in\n         TIMETRA-LOG-MIB::tmnxLogExecRollbackOpTable for this CLI 'exec' or\n         'vsd' operation.\n\n         [EFFECT] All change notifications generated after the generation of\n         this notification and before the tmnxSysExecFinished will be logged in\n         the TIMETRA-LOG-MIB::tmnxLogExecRollbackEventEntry. Once the\n         tmnxSysExecFinished notification is triggered, a Network Management\n         System (NMS) is able to walk the aforementioned log table to retrieve\n         the list of all objects that have been modified during this\n         transaction.\n\n         [RECOVERY] There is no recovery required for this notification.")
tmnxSysExecFinished = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 53)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysExecScript"), ("TIMETRA-SYSTEM-MIB", "tmnxSysExecResult"), ("TIMETRA-LOG-MIB", "tmnxLogExecRollbackOpIndex"), ("TIMETRA-LOG-MIB", "tmnxLogExecRollbackOpType"))
if mibBuilder.loadTexts: tmnxSysExecFinished.setStatus('current')
if mibBuilder.loadTexts: tmnxSysExecFinished.setDescription("[CAUSE] The tmnxSysExecFinished notification is generated upon the\n         completion of the execution of a CLI command file or execution of vsd\n         configuration messages is completed.\n\n         The value of tmnxSysExecScript indicates the command file when the\n         value of tmnxLogExecRollbackOpType is 'exec' or an empty string when\n         the value of tmnxLogExecRollbackOpType is 'vsd'. The value of\n         tmnxLogExecRollbackOpIndex indicates the row entry in\n         TIMETRA-LOG-MIB::tmnxLogExecRollbackOpTable for this CLI 'exec' or\n         'vsd' operation.\n\n         [EFFECT] The effect is that the entry for the specified\n         tmnxLogExecRollbackOpIndex won't be updated, and no further\n         notifications will be added to the specified index in the logger.\n\n         [RECOVERY] When the value of tmnxSysExecResult is 'none' or 'success',\n         no recovery is required.\n\n         When the value is 'fail', the system may be left in an inconsistent\n         state and the user should try to determine the reason for the failure.\n         The user can attempt a recovery by manually entering CLI commands to\n         reverse the failed configuration.  The user can attempt a recovery by\n         performing a rollback revert to a known good checkpoint. The user can\n         attempt a recovery by rebooting the system with the bof pointing to a\n         saved configuration file.")
tmnxSysRollbackSaveStarted = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 54)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysRollbackFileType"))
if mibBuilder.loadTexts: tmnxSysRollbackSaveStarted.setStatus('current')
if mibBuilder.loadTexts: tmnxSysRollbackSaveStarted.setDescription('[CAUSE] The tmnxSysRollbackSaveStarted notification is generated when\n         the user initiates a rollback save as specified by\n         tmnxSysRollbackFileType.\n\n         [EFFECT] The specified configuration file is saved.\n\n         [RECOVERY] There is no recovery required for this notification.')
tmnxSysRollbackDeleteStarted = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 55)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysRollbackIndex"), ("TIMETRA-SYSTEM-MIB", "tmnxSysRollbackFileType"))
if mibBuilder.loadTexts: tmnxSysRollbackDeleteStarted.setStatus('current')
if mibBuilder.loadTexts: tmnxSysRollbackDeleteStarted.setDescription('[CAUSE] The tmnxSysRollbackDeleteStarted notification is generated\n         when the user initiates a rollback delete as specified by\n         tmnxSysRollbackIndex and tmnxSysRollbackFileType.\n\n         [EFFECT] The specified configuration file is deleted.\n\n         [RECOVERY] There is no recovery required for this notification.')
tmnxSysNvsysFileError = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 56)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysFileErrorType"))
if mibBuilder.loadTexts: tmnxSysNvsysFileError.setStatus('current')
if mibBuilder.loadTexts: tmnxSysNvsysFileError.setDescription('[CAUSE] The tmnxSysNvsysFileError notification is generated when there\n         is a failure in accessing the nvsys file as specified by\n         tmnxSysFileErrorType.\n\n         [EFFECT] The specified nvsys file operation is unsuccessful.\n\n         [RECOVERY] The user should investigate why the failure occurred. A\n         failure can indicate a problem with the compact flash.')
sysDNSSecFailedAuthentication = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 57)).setObjects(("TIMETRA-SYSTEM-MIB", "sysDNSSecRespCtrl"), ("TIMETRA-SYSTEM-MIB", "tmnxSysDNSSecDomainName"))
if mibBuilder.loadTexts: sysDNSSecFailedAuthentication.setStatus('current')
if mibBuilder.loadTexts: sysDNSSecFailedAuthentication.setDescription("[CAUSE] The sysDNSSecFailedAuthentication notification is generated\n         when a DNS response PDU is received with an unset AD-bit and\n         sysDNSSecAdValidation is set to 'true (1)'.\n\n         [EFFECT] This notification is informational only. The message will\n         vary depending on the state of sysDNSSecRespCtrl.\n\n         [RECOVERY] There is no recovery required for this notification.")
tmnxConfigConflict = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 58)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxNotifyRow"), ("TIMETRA-SYSTEM-MIB", "tmnxNotifyEntryOID"), ("TIMETRA-SYSTEM-MIB", "tmnxNotifyObjectName"))
if mibBuilder.loadTexts: tmnxConfigConflict.setStatus('current')
if mibBuilder.loadTexts: tmnxConfigConflict.setDescription('A tmnxConfigConflict notification is generated when a configuration\n         attribute associated with a row entry in a MIB table is in conflict\n         with another attribute.\n\n         It can be used by the NMS to trigger maintenance polls of the\n         configuration information.')
tmnxSysLicenseInvalid = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 59)).setObjects(("TIMETRA-CHASSIS-MIB", "tmnxHwClass"), ("TIMETRA-SYSTEM-MIB", "tmnxSysLicenseErrorReason"), ("TIMETRA-SYSTEM-MIB", "tmnxSysLicenseTimeLeft"), ("TIMETRA-SYSTEM-MIB", "tmnxSysLicenseErrorAction"))
if mibBuilder.loadTexts: tmnxSysLicenseInvalid.setStatus('current')
if mibBuilder.loadTexts: tmnxSysLicenseInvalid.setDescription('[CAUSE] The tmnxSysLicenseInvalid notification is generated when the\n         license becomes invalid for the reason specified in\n         tmnxSysLicenseErrorReason.\n\n         [EFFECT] The CPM or system will reboot at the end of the time\n         remaining, as specified by tmnxSysLicenseTimeLeft and\n         tmnxSysLicenseErrorAction.\n\n         [RECOVERY] Configure a valid license file location and file name,\n         given the value of tmnxSysLicenseErrorReason.')
tmnxSysLicenseExpiresSoon = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 60)).setObjects(("TIMETRA-CHASSIS-MIB", "tmnxHwClass"), ("TIMETRA-SYSTEM-MIB", "tmnxSysLicenseTimeLeft"))
if mibBuilder.loadTexts: tmnxSysLicenseExpiresSoon.setStatus('current')
if mibBuilder.loadTexts: tmnxSysLicenseExpiresSoon.setDescription('[CAUSE] The tmnxSysLicenseExpiresSoon notification is generated when\n         the license is due to expire soon.\n\n         [EFFECT] The system will reboot at the end of the time remaining, as\n         specified by tmnxSysLicenseTimeLeft.\n\n         [RECOVERY] Configure a valid license file location and file name.')
tmnxSysVsdServerAvailable = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 63)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysNotifVsdServerName"))
if mibBuilder.loadTexts: tmnxSysVsdServerAvailable.setStatus('current')
if mibBuilder.loadTexts: tmnxSysVsdServerAvailable.setDescription('[CAUSE] The tmnxSysVsdServerAvailable notification is generated when\n         system discover a new VSD server.\n\n         [EFFECT] System will use this information to establish communication\n         with new VSD server as needed.\n\n         [RECOVERY] None needed.')
tmnxSysVsdServerUnavailable = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 64)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysNotifVsdServerName"))
if mibBuilder.loadTexts: tmnxSysVsdServerUnavailable.setStatus('current')
if mibBuilder.loadTexts: tmnxSysVsdServerUnavailable.setDescription('[CAUSE] The tmnxSysVsdServerAvailable notification is generated when\n         system loses connection to VSD.\n\n         [EFFECT] System will use this information and stop communication with\n         this VSD server as needed.\n\n         [RECOVERY] None needed.')
tmnxSysXmppServerFunctional = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 65)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysNotifXmppServerName"))
if mibBuilder.loadTexts: tmnxSysXmppServerFunctional.setStatus('current')
if mibBuilder.loadTexts: tmnxSysXmppServerFunctional.setDescription('[CAUSE] The tmnxSysXmppServerFunctional notification is generated when\n         system discover a new XMPP server.\n\n         [EFFECT] System will use this information to establish communication\n         with new XMPP server as needed.\n\n         [RECOVERY] None needed.')
tmnxSysXmppServerNotFunctional = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 66)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysNotifXmppServerName"))
if mibBuilder.loadTexts: tmnxSysXmppServerNotFunctional.setStatus('current')
if mibBuilder.loadTexts: tmnxSysXmppServerNotFunctional.setDescription('[CAUSE] The tmnxSysXmppServerNotFunctional notification is generated\n         when system can not communicate with XMPP server.\n\n         [EFFECT] Communication with XMPP server will stop.\n\n         [RECOVERY] Check to see why XMPP server has stopped communicating.')
tmnxSysLicenseValid = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 67)).setObjects(("TIMETRA-CHASSIS-MIB", "tmnxHwClass"))
if mibBuilder.loadTexts: tmnxSysLicenseValid.setStatus('current')
if mibBuilder.loadTexts: tmnxSysLicenseValid.setDescription('[CAUSE] The tmnxSysLicenseValid notification is generated once after\n         the system boots up and the license is determined by the system to be\n         valid.\n\n         [EFFECT] The system is running with the license specified in\n         tmnxSysLicenseName.\n\n         [RECOVERY] No recovery.')
tmnxSysBaseMacAddressNotSet = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 68)).setObjects(("TIMETRA-CHASSIS-MIB", "tmnxChassisBaseMacAddress"))
if mibBuilder.loadTexts: tmnxSysBaseMacAddressNotSet.setStatus('current')
if mibBuilder.loadTexts: tmnxSysBaseMacAddressNotSet.setDescription('[CAUSE] The tmnxSysBaseMacAddressNotSet notification is generated once\n         after the system boots up and the value of sbiSystemBaseMacAddress is\n         all zeroes.\n\n         [EFFECT] The system software is using the base MAC address specified\n         in tmnxChassisBaseMacAddress which may not be unique.\n\n         [RECOVERY] Configure sbiSystemBaseMacAddress to a value other than all\n         zeroes.')
tmnxSmLaunchStartFailed = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 69)).setObjects(("TIMETRA-LOG-MIB", "tmnxEhsHEntryScriptPlcyOwner"), ("TIMETRA-LOG-MIB", "tmnxEhsHEntryScriptPlcyName"), ("DISMAN-SCRIPT-MIB", "smLaunchScriptOwner"), ("DISMAN-SCRIPT-MIB", "smLaunchScriptName"), ("DISMAN-SCRIPT-MIB", "smLaunchError"), ("TIMETRA-SYSTEM-MIB", "tmnxSmLaunchExtAuthType"), ("TIMETRA-SYSTEM-MIB", "tmnxSmRunExtAuthType"), ("TIMETRA-SYSTEM-MIB", "tmnxSmRunExtUserName"))
if mibBuilder.loadTexts: tmnxSmLaunchStartFailed.setStatus('current')
if mibBuilder.loadTexts: tmnxSmLaunchStartFailed.setDescription("[CAUSE] The tmnxSmLaunchStartFailed notification is generated when the\n         launch start fails because of one of the following reasons:\n            1. The values of smLaunchScriptOwner and smLaunchScriptName don't\n            have an existing entry in the smScriptTable.\n            2. The value of smScriptOperStatus is not 'enabled'.\n            3. The smScriptSource value is NULL.\n            4. The value of smLaunchOperStatus object in smLaunchTable is not\n            'enabled'.\n            5. The check to see if the run Index is already in use fails.\n            6. The number of currently executing scripts invoked from this\n            smLaunchTable entry is greater than smLaunchMaxRunning.\n\n          [EFFECT] The result is indicated by incrementing the value of\n            tmnxEhsHEntryStatsErrLaunch.\n          [RECOVERY] No recovery is necessary.")
tmnxEhsHandlerInvoked = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 70)).setObjects(("TIMETRA-LOG-MIB", "tmnxEhsHandlerDescription"), ("TIMETRA-SYSTEM-MIB", "tmnxSmRunExtAuthType"), ("TIMETRA-SYSTEM-MIB", "tmnxSmRunExtUserName"))
if mibBuilder.loadTexts: tmnxEhsHandlerInvoked.setStatus('current')
if mibBuilder.loadTexts: tmnxEhsHandlerInvoked.setDescription('[CAUSE] The tmnxEhsHandlerInvoked notification is generated when the\n         following checks pass: 1. A check to see if a event trigger is present\n         for a particular log event based on the log event application-id and\n         event-id/event name. 2. Evaluation of the log filter associated with\n         the trigger-entry.\n\n         [EFFECT] This may create a run entry to execute scripts.\n\n         [RECOVERY] No recovery is necessary.')
tmnxEhsDroppedByMinDelay = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 71)).setObjects(("TIMETRA-LOG-MIB", "tmnxEhsHEntryScriptPlcyOwner"), ("TIMETRA-LOG-MIB", "tmnxEhsHEntryScriptPlcyName"), ("DISMAN-SCRIPT-MIB", "smLaunchScriptOwner"), ("DISMAN-SCRIPT-MIB", "smLaunchScriptName"), ("TIMETRA-LOG-MIB", "tmnxEhsHEntryMinDelay"), ("TIMETRA-LOG-MIB", "tmnxEhsHEntryMinDelayInterval"), ("TIMETRA-SYSTEM-MIB", "tmnxSmRunExtAuthType"), ("TIMETRA-SYSTEM-MIB", "tmnxSmRunExtUserName"))
if mibBuilder.loadTexts: tmnxEhsDroppedByMinDelay.setStatus('current')
if mibBuilder.loadTexts: tmnxEhsDroppedByMinDelay.setDescription('[CAUSE] The tmnxEhsDroppedByMinDelay is generated when two consecutive\n         executions of script policy specified by the same event handler entry\n         occurs within the time period specified by tmnxEhsHEntryMinDelay.\n\n         [EFFECT] The value of tmnxEhsHEntryStatsErrMinDelay gets incremented.\n\n         [RECOVERY] No recovery is necessary.')
tmnxSysAppStats24HrsAvailable = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 72)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysNotifAppStatsTime"), ("TIMETRA-SYSTEM-MIB", "tmnxSysNotifAppStatsApplication"), ("TIMETRA-SYSTEM-MIB", "tmnxSysNotifAppStatsType"))
if mibBuilder.loadTexts: tmnxSysAppStats24HrsAvailable.setStatus('current')
if mibBuilder.loadTexts: tmnxSysAppStats24HrsAvailable.setDescription('[CAUSE] The system generates the tmnxSysAppStats24HrsAvailable\n         notification when new rows are available in the\n         tmnxSysAppStats24HrsTable.\n\n         The value of tmnxSysNotifAppStatsTime indicates the time the system\n         collected the values in the new rows.\n\n         A non-zero value of tmnxSysNotifAppStatsApplication indicates the\n         application; a zero value of tmnxSysNotifAppStatsApplication indicates\n         that new values are available for all active applications.\n\n         A non-zero value of tmnxSysNotifAppStatsType indicates the type of\n         statistics; a zero value of tmnxSysNotifAppStatsType indicates that\n         new values are available for all active types.\n\n         [EFFECT] None.\n\n         [RECOVERY] No recovery is necessary.')
tmnxSysAppStatsWeekAvailable = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 73)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysNotifAppStatsTime"))
if mibBuilder.loadTexts: tmnxSysAppStatsWeekAvailable.setStatus('current')
if mibBuilder.loadTexts: tmnxSysAppStatsWeekAvailable.setDescription('[CAUSE] The system generates the tmnxSysAppStatsWeekAvailable\n         notification when new rows are available in the\n         tmnxSysAppStatsWeekTable.\n\n         The value of tmnxSysNotifAppStatsTime indicates the time the system\n         collected the values in the new rows.\n\n         [EFFECT] None.\n\n         [RECOVERY] No recovery is necessary.')
tmnxSysLicenseActivated = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 75)).setObjects(("TIMETRA-CHASSIS-MIB", "tmnxHwClass"))
if mibBuilder.loadTexts: tmnxSysLicenseActivated.setStatus('current')
