tmnxSysStandbyLicensingError = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 76)).setObjects(("TIMETRA-CHASSIS-MIB", "tmnxHwClass"), ("TIMETRA-SYSTEM-MIB", "tmnxSysLicenseErrorReason"))
if mibBuilder.loadTexts: tmnxSysStandbyLicensingError.setStatus('current')
if mibBuilder.loadTexts: tmnxSysStandbyLicensingError.setDescription('[CAUSE] The tmnxSysStandbyLicensingError notification is generated\n         when a licensing issue has been detected by the standby. The reason is\n         specified in tmnxSysLicenseErrorReason.\n\n         [EFFECT] The Standby CPM may not synchronized and may be put into a\n         failed state depending on the failure.\n\n         [RECOVERY] Ensure a valid license file location and file name,\n         given the value of tmnxSysLicenseErrorReason.  Reset the Standby CPM or activate\n         a valid license.')
tmnxSysStandbyLicensingReady = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 77)).setObjects(("TIMETRA-CHASSIS-MIB", "tmnxHwClass"))
if mibBuilder.loadTexts: tmnxSysStandbyLicensingReady.setStatus('current')
if mibBuilder.loadTexts: tmnxSysStandbyLicensingReady.setDescription('[CAUSE] The tmnxSysStandbyLicensingReady notification is generated\n         when a licensing has been successfully activated by the standby.\n\n         [EFFECT] Any licensing errors detected by the Standby CPM are cleared.\n\n         [RECOVERY] None.')
tmnxSysMgmtIfModeChangeStart = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 78)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxNotifySysMgmtIfOriginalMode"), ("TIMETRA-SYSTEM-MIB", "tmnxSysMgmtIfWriteMode"), ("TIMETRA-SYSTEM-MIB", "tmnxSysMgmtIfWriteSwitchReason"))
if mibBuilder.loadTexts: tmnxSysMgmtIfModeChangeStart.setStatus('current')
if mibBuilder.loadTexts: tmnxSysMgmtIfModeChangeStart.setDescription('[CAUSE] The tmnxSysMgmtIfModeChangeStart notification is generated\n         when a management interface configuration mode change request is sent.\n\n         [EFFECT] Switching modes between any configuration mode will lock the\n         configuration datastores from operator input until the mode switch has\n         completed.\n\n         [RECOVERY] None.')
tmnxSysMgmtIfModeChangeComplete = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 79)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysMgmtIfWriteMode"))
if mibBuilder.loadTexts: tmnxSysMgmtIfModeChangeComplete.setStatus('current')
if mibBuilder.loadTexts: tmnxSysMgmtIfModeChangeComplete.setDescription('[CAUSE] The tmnxSysMgmtIfModeChangeComplete notification is generated\n         when a management interface configuration mode change request is\n         complete.\n\n         [EFFECT] Switching modes between any configuration mode will lock the\n         configuration datastores from operator input until the mode switch has\n         completed. Once this event is triggered the configuration datastores\n         are unlocked for operator input.\n\n         [RECOVERY] None.')
tmnxSysMgmtIfModeChangeFailure = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 80)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysMgmtIfWriteMode"))
if mibBuilder.loadTexts: tmnxSysMgmtIfModeChangeFailure.setStatus('current')
if mibBuilder.loadTexts: tmnxSysMgmtIfModeChangeFailure.setDescription('[CAUSE] The tmnxSysMgmtIfModeChangeFailure notification is generated\n         when a management interface configuration mode change request fails to\n         complete.\n\n         [EFFECT] Switching modes between any configuration mode will lock the\n         configuration datastores from operator input until the mode switch has\n         completed. When this event is triggered the mode change is declared\n         unsuccessful; the effective configuration mode will be indicated in\n         this notification. The configuration datastores are unlocked for\n         operator input.\n\n         [RECOVERY] None.')
tmnxSysAppLicenseInsufficient = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 81)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxSysLicensingNotifyGroup"), ("TIMETRA-SYSTEM-MIB", "tmnxSysLicensedNotifyAppName"), ("TIMETRA-SYSTEM-MIB", "tmnxSysAppLicenseState"), ("TIMETRA-SYSTEM-MIB", "tmnxSysLicenseErrorReason"))
if mibBuilder.loadTexts: tmnxSysAppLicenseInsufficient.setStatus('current')
if mibBuilder.loadTexts: tmnxSysAppLicenseInsufficient.setDescription('[CAUSE] The tmnxSysAppLicenseInsufficient notification is generated periodically\n         when licensing for an application is detected to be insufficient.  The details\n         of the error is specified in tmnxSysLicenseErrorReason.\n         This notification cannot be suppressed.\n\n         [EFFECT] Notification generated periodically while the application\n         remains in this condition.\n\n         [RECOVERY] Activate a system license containing sufficient license\n         entitlements for this application.')
tmnxSysMgmtIfLiIncorrectFormat = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 82)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxPrimaryConfigFileFormatType"), ("TIMETRA-SYSTEM-MIB", "tmnxLiConfigFileFormatType"))
if mibBuilder.loadTexts: tmnxSysMgmtIfLiIncorrectFormat.setStatus('current')
if mibBuilder.loadTexts: tmnxSysMgmtIfLiIncorrectFormat.setDescription('[CAUSE] The tmnxSysMgmtIfLiIncorrectFormat notification is generated\n         when a format (classic or model-driven) of the Lawful Intercept (LI)\n         configuration file does not match primary configuration file format.\n\n         [EFFECT] The Lawful Intercept (LI) configuration file is not loaded\n         during the boot.\n\n         [RECOVERY] Reboot with the correct Lawful Intercept (LI) configuration\n         file')
tmnxSysMgmtIfLiCfgNotEncrypted = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 83))
if mibBuilder.loadTexts: tmnxSysMgmtIfLiCfgNotEncrypted.setStatus('current')
if mibBuilder.loadTexts: tmnxSysMgmtIfLiCfgNotEncrypted.setDescription('[CAUSE] The tmnxSysMgmtIfLiCfgNotEncrypted notification is generated\n         when the Lawful Intercept (LI) configuration file is not encrypted.\n\n         [EFFECT] The Lawful Intercept (LI) configuration file is not loaded\n         during the boot.\n\n         [RECOVERY] Reboot with the correct Lawful Intercept (LI) configuration\n         file')
tmnxSysLicenseUpdateRequired = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 84)).setObjects(("TIMETRA-CHASSIS-MIB", "tmnxHwClass"))
if mibBuilder.loadTexts: tmnxSysLicenseUpdateRequired.setStatus('current')
if mibBuilder.loadTexts: tmnxSysLicenseUpdateRequired.setDescription('[CAUSE] The tmnxSysLicenseUpdateRequired notification is generated once after\n         the system boots up and the license is determined by the system to be  valid, but\n         requires to be updated to the correct software version.\n\n         [EFFECT] The system will use the license until it is updated.\n\n         [RECOVERY] Update and activate the updated license.')
tmnxEqOperStateChange = NotificationType((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 0, 85)).setObjects(("TIMETRA-SYSTEM-MIB", "tmnxNotifyRow"), ("TIMETRA-SYSTEM-MIB", "tmnxNotifyRowOperState"), ("TIMETRA-SYSTEM-MIB", "tmnxNotifyEntryOID"), ("TIMETRA-SYSTEM-MIB", "tmnxNotifyObjectName"))
if mibBuilder.loadTexts: tmnxEqOperStateChange.setStatus('current')
if mibBuilder.loadTexts: tmnxEqOperStateChange.setDescription('[CAUSE] The tmnxEqOperStateChange notification is generated when a\n         change occurred in the operational state on the piece of hardware.\n\n         [EFFECT] If the state has changed to out of service, then all ports\n         and services associated with the module change to out of service and\n         traffic is impacted.\n\n         [RECOVERY] Investigation is required to determine the cause of the\n         change.')
tmnxSysMGNotifications = MibIdentifier((1, 3, 6, 1, 4, 1, 6527, 3, 1, 3, 1, 1))
